Select * from customer_data
Limit 5;

--Q1. What is the total revenue generated by male and female customers.
Select gender,sum(purchase_amount) from customer_data
group by gender;

--Q2. Which customer used a discount but still spent more than the average purchase amount?
Select customer_id, purchase_amount from customer_data
where discount_applied = 'Yes' and purchase_amount>=(select avg(purchase_amount) from customer_data as avg_amount);

--Q3. What are the top 5 products with the highest average review ratings
Select item_purchased, round(AVG(review_rating::numeric),2) as Average_ratings from customer_data
group by item_purchased
order by AVG(review_rating) DESC
limit 5;

--Q4. Compare the Average purchase amount between Standard and Express shipping.
Select shipping_type, round(AVG(purchase_amount::numeric),2) from customer_data
where shipping_type in ('Standard','Express')
group by shipping_type
;

-- Q5. Do subscribed customers spend more? Compare average spend and total revenue 
--between subscribers and non-subscribers.
Select subscription_status, round(AVG(purchase_amount::numeric),2), Sum(purchase_amount) from customer_data
Group by subscription_status;

SELECT subscription_status,
       COUNT(customer_id) AS total_customers,
       ROUND(AVG(purchase_amount),2) AS avg_spend,
       ROUND(SUM(purchase_amount),2) AS total_revenue
FROM customer_data
GROUP BY subscription_status
ORDER BY total_revenue,avg_spend DESC;

-- Q6. Which 5 products have the highest percentage of purchases with discount applied?
Select item_purchased, 
Round(100*sum(case when discount_applied = 'Yes' then 1 else 0 end)/ Count(*),2) as discount_rate
from customer_data
group by item_purchased
order by discount_rate DESC
Limit 10;

--Q7. Segment customers into New, Returning, and Loyal based on their total 
-- number of previous purchases, and show the count of each segment. 
with customer_type as (
select customer_id, previous_purchases,
	case
		when previous_purchases = 1 then 'New'
		when previous_purchases between 2 and 10 then 'Returning'
		else 'Loyal'
		End as customer_segment
from customer_data
)
select customer_segment, count(*) as "Number of Customers" from customer_type
group by customer_segment;

--Q8. What are the top 3 most purchased products within each category? 
with item_counts as (
select category, item_purchased,
Count(customer_id) as total_orders,
row_number() over(partition by category order by count(customer_id )desc)as item_rank
from customer_data
group by category, item_purchased
)
select item_rank, category, item_purchased, total_orders from item_counts
where item_rank <=3;

--Q9. Are customers who are repeat buyers (more than 5 previous purchases) also likely to subscribe?
Select subscription_status, Count(customer_id) as repeat_buyers
FROM customer_data
WHERE previous_purchases > 5
GROUP BY subscription_status;

--Q10. What is the revenue contribution of each age group.
Select age_group, sum(purchase_amount) as revenue_contribution
from customer_data
group by age_group
order by revenue_contribution desc;










